import React from 'react';
import { StyleSheet, View } from 'react-native';
import { StatusBar } from 'expo-status-bar';
import { WebView } from 'react-native-webview';
import { HTML_CONTENT } from './src/htmlContent';

// The bubble map is a fully self-contained HTML page (data snapshot embedded).
// It is bundled as a string module (src/htmlContent.ts, generated by
// scripts/sync-html.mjs from ../42-bubblemap/index.html) and rendered
// full-screen in a WebView. No network access is needed or allowed.
export default function App() {
  return (
    <View style={styles.root}>
      <StatusBar style="light" />
      <WebView
        source={{ html: HTML_CONTENT, baseUrl: 'https://localhost/' }}
        originWhitelist={['*']}
        javaScriptEnabled
        domStorageEnabled={false}
        style={styles.webview}
        containerStyle={styles.webview}
        onShouldStartLoadWithRequest={(req) =>
          req.url === 'https://localhost/' ||
          req.url.startsWith('about:') ||
          req.url.startsWith('data:')
        }
        setSupportMultipleWindows={false}
        overScrollMode="never"
        textZoom={100}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1, backgroundColor: '#050914' },
  webview: { flex: 1, backgroundColor: '#050914' },
});
